import{_ as e,o as i,c as r,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph User Survey Working Group 2020-11-05","description":"","frontmatter":{"title":"Ceph User Survey Working Group 2020-11-05","date":"2020-11-05T00:00:00.000Z","updated":"2020-11-24T00:00:00.000Z","tags":["Ceph","用户调查","分布式存储","CRUSH 算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","Bluestore","BlueFS","RocksDB","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","身份验证","授权","加密","纠错码","复制","快照","克隆","虚拟化","云计算","AWS","Azure","Google Cloud","混合云","多云","存储集群","节点","存储","SSD","HDD","JBOD","SAN","NAS","网络","网络拓扑","失败域","恢复","弹性","负载均衡","缓存","压缩","去重","分层","性能调优","基准测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_User_Survey_Working_Group_2020-11-05.md","filePath":"posts/2020/Ceph_User_Survey_Working_Group_2020-11-05.md","lastUpdated":1780460162000}'),o={name:"posts/2020/Ceph_User_Survey_Working_Group_2020-11-05.md"};function t(s,l,n,u,p,_){return i(),r("div",null,[...l[0]||(l[0]=[a('<p>会议纪要</p><h3 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h3><p>原定五人参会，但因Stefan缺席，实际参会人员为四人。</p><h3 id="会议内容" tabindex="-1">会议内容 <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容&quot;">​</a></h3><ol><li><p><strong>更新与反馈</strong></p><ul><li>参会者对当前更新情况表示好奇，但未获得具体信息。</li><li>参会者分享了上周的待办事项，展示了调查问卷并收到了关于数据收集目的、相关性以及硬件供应商信息对软件开发有用性的反馈。</li></ul></li><li><p><strong>功能与技术讨论</strong></p><ul><li>讨论了缓存功能的使用情况，特别是缓存分层功能，指出Red Hat不支持该功能，只有Suse支持。</li><li>探讨了如何改进调查问卷以更好地识别和优化功能，特别是性能相关功能。</li><li>讨论了从Intel的角度如何利用NVMe技术改进Ceph性能，提到了Crimson项目。</li></ul></li><li><p><strong>调查问卷的改进</strong></p><ul><li>讨论了是否应该深化调查问卷的细节，或保持现有形式。</li><li>提出了获取配置和部署细节的可能性，以帮助改进Ceph的部署和性能。</li><li>讨论了调查问卷的格式和内容，是否应该保持现有格式或进行调整以更好地收集信息。</li></ul></li><li><p><strong>后续行动计划</strong></p><ul><li>决定继续使用现有调查问卷格式，但重新审视和优化问题内容。</li><li>计划重新启用调查问卷，并邀请参会者进行体验和反馈。</li><li>讨论了推广调查问卷的方法，包括通过用户组列表和博客进行宣传，以及通过董事会成员在其组织内推广。</li></ul></li></ol><h3 id="下一步行动" tabindex="-1">下一步行动 <a class="header-anchor" href="#下一步行动" aria-label="Permalink to &quot;下一步行动&quot;">​</a></h3><ul><li>参会者将在Google Docs上编辑调查问卷的问题，并提出改进建议。</li><li>重新启用调查问卷，并邀请参会者进行体验和反馈。</li><li>通过用户组列表和博客进行调查问卷的宣传，并通过董事会成员在其组织内推广。</li><li>计划在下一次会议前，对调查问卷的内容和格式进行进一步的讨论和优化。</li></ul><h3 id="下次会议" tabindex="-1">下次会议 <a class="header-anchor" href="#下次会议" aria-label="Permalink to &quot;下次会议&quot;">​</a></h3><ul><li>计划在下周或下下周进行下一次会议，具体时间将通过Doodle Poll确定。</li></ul><h3 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h3><ul><li>会议中提到了一些技术细节，如NVMe技术、Crimson项目、缓存功能等，这些是Ceph分布式存储系统中的关键技术点。</li><li>参会者对调查问卷的改进和推广表示了积极的态度，并提出了具体的行动计划。</li></ul>',11)])])}const c=e(o,[["render",t]]);export{d as __pageData,c as default};
